// Parameter (ALLY 40, Verkaufsberichte): Sitzung und geprüfte Parameter für shopify_web (bericht = Nummer oder „neu“, archiv = 1).
// Migration 87 (Stefan 22.10.2026): produkte = 1 (Produkte auswählen; q = Suche, pst = Filter, ps = Seite), ordner = 1 (Ordner-Browser; op = Pfad im Bereich „Ally-Dateien“).
const E = $input.first().json;
const P = E.parameter || {};
const f = {};
const txt = v => { const t = String(v ?? '').trim(); return t.length <= 300 && !/[\x00-\x1f\x7f]/.test(t) ? t : ''; };
if (/^[0-9]{1,9}$/.test(String(P.bericht || ''))) f.bericht = String(P.bericht);
if (String(P.archiv || '') === '1') f.archiv = '1';
if (f.bericht && String(P.produkte || '') === '1') {
  f.produkte = '1';
  f.q = txt(P.q).slice(0, 100);
  if (['ACTIVE', 'DRAFT', 'ARCHIVED', 'gewaehlt'].includes(String(P.pst || ''))) f.pst = String(P.pst);
  if (/^[0-9]{1,4}$/.test(String(P.ps || ''))) f.ps = String(P.ps);
}
// Migration 92: mail = Lauf, dessen fertige Mail gezeigt wird (shopify_web prüft, dass der Lauf zum Bericht gehört)
if (f.bericht && /^[0-9]{1,18}$/.test(String(P.mail || ''))) f.mail = String(P.mail);
const ordner = { an: !!f.bericht && String(P.ordner || '') === '1', pfad: txt(P.op).replace(/^\/+|\/+$/g, '') };
return [{ json: { ordner, werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(f)] } }];

// Verkaufsberichte (ALLY 40, Migration 82/85/87, Stefan 22.10.2026): Berichte aus verbundenen Shopify-Shops. Daten aus shopify_web (Rechte prüft die Datenbank).
// Migration 91 (Stefan 22.10.2026, 17:44): Zeitplan mit sieben Häufigkeiten, Uhrzeit im 5-Minuten-Takt, „Nächster Versand“ im Kopf, Versand ohne Zeitplan „nur mit Jetzt senden“.
// Ansichten: Liste (Kopfknopf „Neuer Bericht“), Archiv (archiv=1), neuer Bericht (bericht=neu: nur Name, ggf. Shop), Bericht (bericht=<Nummer>),
// Produkte auswählen (produkte=1: Suche, Filter, 20 je Seite, Haken, „Übernehmen“), Ordner wählen (ordner=1: Ordner-Browser im Bereich „Ally-Dateien“).
// Migration 87 (Stefan 12:58–13:07): EIN Speichern im haftenden Seitenkopf für die ganze Berichtsseite (seite.formular + formular_von), „Bericht erstellen“ als
// Hauptknopf (sofort, ohne Versand), „Jetzt senden“ unter Aktionen (ausgegraut mit Grund), nur ausgewählte Produkte auf der Seite, Zeitraum mit Ergebniszeile,
// abhängige Felder nur bei Bedarf (zeigen_wenn), Partner-Link mit einem Schalter, Speicherort im Klartext, Ordner nur über den Ordner-Browser, Hinweise in Alltagssprache.
// Migration 88 (Stefan 22.10.2026, 16:56): Absender-Auswahl nur mit Postfächern, deren Versand geprüft und erlaubt ist (Schalter „Versand erlauben“).
// Migration 92 (Stefan 22.10.2026, 18:13): Versand mit Betreff und Text der Mail (Platzhalter, Standardtext, Signatur anhängen, Vorschau), „Jetzt versenden“ im Abschnitt
// (ausgegraut mit Grund; Rückfrage mit Empfangenden und Absender; mit ungespeicherten Änderungen erst speichern, dann Bestätigungsfenster senden=1),
// „Mail ansehen“ im Verlauf (mail=<Lauf>, auch Testmodus „würde senden“).
// Schlussprüfung (Koordination 22.10.2026, Migration 94): Rückfrage und Vorschau von „Jetzt versenden“ zeigen genau die Mail, die jetzt rausgeht (Zeitraum und Datum von heute);
// nur noch „Jetzt versenden“ im Abschnitt Versand (kein zweiter Knopf unter Aktionen); der nächste Termin steht nur im Kopf und in der Ergebniszeile des Zeitplans;
// Hinweis bei festem Zeitraum mit Zeitplan; Datum überall „1.9.2026“.
// Migration 98 (Stefan 22.10.2026, 21:34/21:35/21:38): Inhalt mit festen Zahlen Umsatz netto (ohne USt.) und Umsatz brutto (mit USt.), wählbar Überleitung zum Umsatz,
// Mengen, Varianten, Vergleich (kein, Zeitraum davor, Vorjahr) und Entwicklung. Verlauf: je Zeile „Entfernen“ (archivieren, Rückfrage im Popup) und „Mehrere entfernen“
// auf eigener Seite (verlauf=entfernen, 20 je Seite); im Ordner gelöschte Dateien als „Datei gelöscht“ statt Link (Prüfung durch SHOPIFY 3).
// Der frühere Knoten „Ergänzungen“ (Migration 97: Platzhalter {Name} in der Signatur, Name für die Vorschau) ist hier eingearbeitet.
// Migration 100 (Prüfung 23.10.2026): i-Texte höchstens zwei kurze Sätze; „Zusätzlich im Bericht“ als eine Auswahl (Überleitung, Mengen, Varianten) statt einzelner Haken;
// „Mehrere Einträge entfernen“ mit „Alle auf dieser Seite auswählen“, Sortierung und einheitlichem Namen; kein Zahnrad „Shops verwalten“ auf Unterseiten;
// Hinweis zu „Datei gelöscht“ ohne feste Minutenzahl; „berechnet“ statt „bezahlt“.
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const PA = $('Parameter').first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
const titel = s(F.name || 'Verkaufsberichte');
const SEITE = 'verkaufsberichte';
const hier = p => ({ seite: SEITE, parameter: p || {} });
const krumen0 = [{ text: 'Startseite', ziel: { seite: 'start' } }];
const kopf = { schluessel: SEITE, art: 'funktion', titel, beschreibung: s(F.beschreibung || 'Verkaufszahlen einzelner Produkte als PDF oder CSV, per Mail, im Speicherort oder über einen Partner-Link.'),
  krumen: krumen0.concat([{ text: titel }]) };
const R = D.r;
if (D.ok !== true || !R || R.ok !== true)
  return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: s((R && R.fehler) || 'Die Verkaufsberichte konnten nicht geladen werden. Bitte neu laden.') }] } } }];
const ZU = D.zustand && typeof D.zustand === 'object' ? D.zustand : {};
const ADMIN = R.admin === true;
const zielShops = { seite: 'einstellungen', parameter: { bereich: 'shops' } };
if (ADMIN) kopf.zahnrad = { ziel: zielShops, label: 'Shops verwalten' };
const SHOPS = L(R.shops).filter(x => x && id9(x.id));
const VERBUNDEN = SHOPS.filter(x => x.verbunden);
const ZR = L(R.zeitraeume).filter(z => z && /^[a-z0-9_]{1,20}$/.test(s(z.k)));
const POST = L(R.postfaecher).filter(p => p && s(p.adresse));
const ABL = R.ablage && typeof R.ablage === 'object' ? R.ablage : {};
const SYS = R.system_absender && typeof R.system_absender === 'object' ? R.system_absender : {};
const statusMarke = st => st === 'fertig' ? { text: 'Erstellt', ton: 'ok' } : st === 'fehler' ? { text: 'Fehler', ton: 'warn' } : st === 'laeuft' ? { text: 'Läuft', ton: 'info' } : st === 'offen' ? { text: 'Wartet', ton: 'grau' } : null;
const produktStatus = st => st === 'DRAFT' ? 'Entwurf' : st === 'ARCHIVED' ? 'Archiviert' : st === 'UNLISTED' ? 'Nicht gelistet' : st === 'ACTIVE' ? 'Aktiv' : '';
const ohneShop = () => [{ typ: 'text', ton: 'grau', text: ADMIN ? 'Noch kein Shop verbunden. Zuerst einen Shopify-Shop verbinden.' : 'Noch kein Shop verbunden. Das richtet eine Person mit der Rolle Admin ein.' }]
  .concat(ADMIN ? [{ typ: 'aktion', text: 'Shop verbinden', ziel: { seite: 'einstellungen', parameter: { bereich: 'shops', neu: '1' } } }] : []);
const zusammen = (...t) => t.filter(Boolean).join(' · ');
const anzAdr = n => n + (n === 1 ? ' Adresse' : ' Adressen');
const groesse = b => !(Number(b) > 0) ? '' : b < 1024 ? b + ' B' : b < 1048576 ? (Math.round(b / 102.4) / 10).toLocaleString('de-DE') + ' KB' : (Math.round(b / 104857.6) / 10).toLocaleString('de-DE') + ' MB';
const datumDE = d => /^\d{4}-\d{2}-\d{2}$/.test(s(d)) ? s(d).split('-').reverse().map(x => String(Number(x))).join('.') : '';
// Sortierung je Person (Schlüssel verkaufsberichte.<Tabelle>): erlaubte Spalten, sonst Standard
const sortierung = (tid, erlaubt, std) => { const so = (ZU[SEITE + '.' + tid] || {}).sortierung || {};
  return { spalte: erlaubt.includes(so.spalte) ? so.spalte : std.spalte, richtung: ['auf', 'ab'].includes(so.richtung) ? so.richtung : std.richtung }; };
const sortiere = (liste, so, wert) => liste.slice().sort((a, b) => { const x = wert(a, so.spalte), y = wert(b, so.spalte);
  const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y), 'de', { numeric: true, sensitivity: 'base' }); return so.richtung === 'ab' ? -c : c; });
const zeitWert = t => { const m = /^(\d{1,2})\.(\d{1,2})\.(\d{4}), (\d{2}):(\d{2})$/.exec(s(t)); return m ? Number(m[3] + m[2].padStart(2, '0') + m[1].padStart(2, '0') + m[4] + m[5]) : 0; };
const dateiZiel = id => ({ seite: 'datei', parameter: { sb: s(id) } });
const zrTxt = t => s(t).replace(/\b0?(\d{1,2})\.0?(\d{1,2})\.(\d{4})\b/g, '$1.$2.$3').replace(/(\d{4}) bis (\d)/, '$1 – $2');
// kurzer Zeitraum für die Kennzahlen oben: „1.9.–30.9.2026“ (gleiches Jahr), sonst unverändert
const kurzZR = t => { const m = /^(\d{1,2}\.\d{1,2}\.)(\d{4}) – (\d{1,2}\.\d{1,2}\.)(\d{4})$/.exec(s(t)); return m && m[2] === m[4] ? m[1] + '–' + m[3] + m[4] : s(t); };

let abschnitte = [], bloecke = null, fenster = [];
const B = R.bericht && typeof R.bericht === 'object' && id9(R.bericht.id) ? R.bericht : null;

if (P.bericht === 'neu') {
  // ---------- Neuer Bericht: nur Name (und Shop, wenn es mehrere gibt) ----------
  kopf.titel = 'Neuer Verkaufsbericht';
  kopf.beschreibung = 'Gib dem Bericht einen Namen. Danach wählst du die Produkte aus.';
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: 'Neuer Bericht' }]);
  kopf.zustand_teil = 'neu';
  abschnitte = [{ id: 'neu', titel: 'Neuer Bericht', offen_standard: true,
    inhalt: VERBUNDEN.length ? [{ typ: 'formular', id: 'bericht-neu', aktion: 'sh_bericht_speichern', werte: { teil: 'neu' }, spalten: 1, felder: [
      { typ: 'text', name: 'name', label: 'Name des Berichts', pflicht: true, platzhalter: 'z. B. Schneidebretter für Partnerfirma X', info: 'So heißt der Bericht in Ally, im PDF und im Betreff der Mail.' }]
      .concat(VERBUNDEN.length > 1 ? [{ typ: 'auswahl', name: 'shop_id', label: 'Shop', wert: id9(VERBUNDEN[0].id), info: 'Ein Bericht zeigt Produkte aus genau einem Shop.',
        optionen: VERBUNDEN.map(x => ({ wert: id9(x.id), text: s(x.name) + (x.domain ? ' (' + s(x.domain) + ')' : '') })) }] : []),
      knoepfe: [{ text: 'Bericht anlegen und Produkte auswählen' }] }] : ohneShop() }];
} else if (id9(P.bericht) && !B) {
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: 'Bericht' }]);
  bloecke = [{ typ: 'hinweis', ton: 'warn', text: 'Diesen Bericht gibt es nicht.' }, { typ: 'aktion', text: 'Zu den Verkaufsberichten', ziel: hier() }];
} else if (B && P.produkte === '1') {
  delete kopf.zahnrad;  // Migration 100: „Shops verwalten“ nur auf Liste und Bericht
  // ---------- Produkte auswählen: Suche, Filter, 20 je Seite, Haken, „Übernehmen“ ----------
  const bid = id9(B.id), A = R.auswahl && typeof R.auswahl === 'object' ? R.auswahl : { zeilen: [], gesamt: 0, seite: 1, je_seite: 20 };
  const Z = L(A.zeilen).filter(x => x && /^[0-9]{1,18}$/.test(s(x.id)));
  const seiten = Math.max(1, Math.ceil(Number(A.gesamt || 0) / Number(A.je_seite || 20))), ps = Math.min(seiten, Math.max(1, Number(A.seite) || 1));
  kopf.titel = 'Produkte auswählen';
  kopf.beschreibung = 'Haken setzen und „Übernehmen“ klicken. Produkte auf anderen Seiten bleiben, wie sie sind.';
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: s(B.name), ziel: hier({ bericht: bid }) }, { text: 'Produkte auswählen' }]);
  kopf.zustand_teil = 'produkte-waehlen';
  const formular = Z.length ? [{ typ: 'formular', id: 'produkte-waehlen', aktion: 'sh_produkte_uebernehmen', spalten: 1,
    werte: { bericht_id: bid, sichtbar: Z.map(x => s(x.id)).join(','), q: s(A.q), pst: s(A.pst) },
    felder: [{ typ: 'mehrfach', name: 'produkte', label: 'Produkte auf dieser Seite', breite: 'voll', wert: Z.filter(x => x.gewaehlt).map(x => s(x.id)),
      optionen: Z.map(x => ({ wert: s(x.id), text: s(x.titel), neben: zusammen(produktStatus(s(x.status)), Number(x.varianten) > 1 ? x.varianten + ' Varianten' : '') })) }],
    knoepfe: (ps > 1 ? [{ text: '‹ Vorherige Seite', art: 'neben', name: 'gehe', wert: String(ps - 1) }] : [])
      .concat(ps < seiten ? [{ text: 'Nächste Seite ›', art: 'neben', name: 'gehe', wert: String(ps + 1) }] : []).concat([{ text: 'Abbrechen', schliesst: true }, { text: 'Übernehmen' }]),
    schliessen_ziel: hier({ bericht: bid }) }]
    : [{ typ: 'text', ton: 'grau', text: s(A.q) || s(A.pst) ? 'Keine Produkte für diese Suche.' : 'Im Shop gibt es noch keine Produkte. Sie werden regelmäßig aus Shopify geladen.' }];
  abschnitte = [{ id: 'auswahl', titel: 'Produkte im Shop', zahl: String(Number(A.gewaehlt || 0)) + ' ausgewählt', offen_standard: true,
    info: ['Haken bei den Produkten setzen, deren Verkaufszahlen im Bericht stehen sollen. Beim Blättern wird die Auswahl der aktuellen Seite mitgespeichert.'],
    inhalt: [{ typ: 'filter', id: 'produkte-filter', label: 'Produkte suchen', felder: [
      { typ: 'text', name: 'q', label: 'Suche im Produktnamen', wert: s(A.q), platzhalter: 'z. B. Brett', autocomplete: 'off' },
      { typ: 'auswahl', name: 'pst', label: 'Anzeigen', wert: s(A.pst), optionen: [{ wert: '', text: 'Alle Produkte' }, { wert: 'gewaehlt', text: 'Nur ausgewählte' },
        { wert: 'ACTIVE', text: 'Aktiv' }, { wert: 'DRAFT', text: 'Entwurf' }, { wert: 'ARCHIVED', text: 'Archiviert' }] }] },
      { typ: 'text', ton: 'grau', text: zusammen(Number(A.gesamt || 0) + (Number(A.gesamt) === 1 ? ' Produkt' : ' Produkte'), 'Seite ' + ps + ' von ' + seiten, 'höchstens 50 je Bericht') }]
      .concat(formular) }];
} else if (B && P.verlauf === 'entfernen') {
  // ---------- Migration 98: Mehrere Einträge aus dem Verlauf entfernen (archivieren), 20 je Seite ----------
  delete kopf.zahnrad;  // Migration 100
  const bid = id9(B.id), LA00 = L(B.laeufe).filter(l => l && /^[0-9]{1,18}$/.test(s(l.id)) && !['offen', 'laeuft'].includes(s(l.status)));
  // Migration 100: Sortierung (neueste zuerst, älteste zuerst, nach Anlass) und „Alle auf dieser Seite auswählen“ (alle=1)
  const vso = ['neu', 'alt', 'anlass'].includes(s(P.vso)) ? s(P.vso) : 'neu', alle = s(P.alle) === '1';
  const LA0 = sortiere(LA00, { spalte: vso === 'anlass' ? 'art' : 'zeit', richtung: vso === 'neu' ? 'ab' : 'auf' },
    (l, k) => k === 'zeit' ? zeitWert(l.zeit) : s(l.art) + ' ' + String(9e12 - zeitWert(l.zeit)));
  const seiten = Math.max(1, Math.ceil(LA0.length / 20)), vs = Math.min(seiten, Math.max(1, Number(P.vs) || 1));
  const Z = LA0.slice((vs - 1) * 20, vs * 20);
  kopf.titel = 'Mehrere Einträge entfernen';
  kopf.beschreibung = 'Haken setzen und „Ausgewählte entfernen“ klicken. Die Einträge werden archiviert, Dateien im Ordner bleiben unverändert.';
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: s(B.name), ziel: hier({ bericht: bid }) }, { text: 'Mehrere Einträge entfernen' }]);
  kopf.zustand_teil = 'verlauf-entfernen';
  const ws = (n, extra) => hier(Object.assign({ bericht: bid, verlauf: 'entfernen', vs: String(n) }, vso !== 'neu' ? { vso } : {}, extra || {}));
  abschnitte = [{ id: 'verlauf-entfernen', titel: 'Verlauf', zahl: String(LA0.length), offen_standard: true,
    info: ['Entfernte Einträge hebt Ally im Archiv auf. Dateien im Ordner bleiben unverändert.'],
    inhalt: Z.length ? [{ typ: 'filter', id: 'verlauf-sortierung', label: 'Sortierung', felder: [{ typ: 'auswahl', name: 'vso', label: 'Sortieren', wert: vso,
        optionen: [{ wert: 'neu', text: 'Neueste zuerst' }, { wert: 'alt', text: 'Älteste zuerst' }, { wert: 'anlass', text: 'Nach Anlass' }] }] },
      { typ: 'text', ton: 'grau', text: zusammen(LA0.length + (LA0.length === 1 ? ' Eintrag' : ' Einträge'), 'Seite ' + vs + ' von ' + seiten) },
      { typ: 'aktion', text: alle ? 'Auswahl aufheben' : 'Alle auf dieser Seite auswählen', ziel: ws(vs, alle ? {} : { alle: '1' }) },
      { typ: 'formular', id: 'verlauf-entfernen', aktion: 'sh_lauf_entfernen', spalten: 1, werte: { bericht_id: bid },
        frage: 'Ausgewählte Einträge aus dem Verlauf entfernen? Sie werden archiviert, nicht gelöscht. Dateien im Ordner bleiben unverändert.',
        felder: [{ typ: 'mehrfach', name: 'laeufe', label: 'Einträge auf dieser Seite', breite: 'voll', wert: alle ? Z.map(l => s(l.id)) : [],
          optionen: Z.map(l => ({ wert: s(l.id), text: zusammen(s(l.zeit), s(l.art)), neben: zusammen(l.zeitraum ? 'Zeitraum ' + zrTxt(l.zeitraum) : '', s((statusMarke(l.status) || {}).text || ''),
            Number(l.im_ordner_geloescht) > 0 ? 'im Ordner gelöscht' : '') })) }],
        knoepfe: [{ text: 'Abbrechen', schliesst: true }, { text: 'Ausgewählte entfernen' }], schliessen_ziel: hier({ bericht: bid }) }]
      .concat(seiten > 1 ? [{ typ: 'aktion', text: '‹ Vorherige Seite', ziel: ws(Math.max(1, vs - 1)), aus: vs <= 1 }, { typ: 'aktion', text: 'Nächste Seite ›', ziel: ws(Math.min(seiten, vs + 1)), aus: vs >= seiten }] : [])
      : [{ typ: 'text', ton: 'grau', text: 'Im Verlauf steht nichts, was sich entfernen lässt.' }, { typ: 'aktion', text: 'Zurück zum Bericht', ziel: hier({ bericht: bid }) }] }];
} else if (B && PA.ordner && PA.ordner.an) {
  delete kopf.zahnrad;  // Migration 100
  // ---------- Ordner wählen: Ordner-Browser im Bereich „Ally-Dateien“ ----------
  const bid = id9(B.id), pf = s(PA.ordner.pfad), teile = pf ? pf.split('/') : [];
  const BER = s(ABL.bereich || 'Ally-Dateien'), ORT = s(ABL.name || 'Speicherort');
  const zu = p => hier(Object.assign({ bericht: bid, ordner: '1' }, p ? { op: p } : {}));
  kopf.titel = 'Ordner für die Ablage wählen';
  kopf.beschreibung = 'Öffne den Ordner, in dem die Dateien landen sollen, und klicke „Diesen Ordner wählen“.';
  kopf.krumen = krumen0.concat([{ text: titel, ziel: hier() }, { text: s(B.name), ziel: hier({ bericht: bid }) }, { text: 'Ordner wählen' }]);
  kopf.zustand_teil = 'ordner-waehlen';
  const OL = $('Ordner lesen (SPEICHER 1)').isExecuted ? ($('Ordner lesen (SPEICHER 1)').first().json || {}) : null;
  const inhalt = [{ typ: 'text', ton: 'grau', text: 'Dateien landen dann in: ' + [ORT, BER].concat(teile).join(' › ') }];
  if (ABL.browser !== true) inhalt.push({ typ: 'text', ton: 'warn', text: 'In diesem Speicherort kann Ally keine Ordner zeigen. Speicherorte richtest du unter Einstellungen › Organisation › Speicherorte ein.' });
  else if (!OL || OL.ok !== true) inhalt.push({ typ: 'text', ton: 'warn', text: s((OL && OL.fehler) || 'Der Speicherort konnte gerade nicht gelesen werden. Bitte später noch einmal versuchen.') });
  else {
    if (OL.hinweis) inhalt.push({ typ: 'text', ton: 'grau', text: s(OL.hinweis) });
    if (pf && OL.vorhanden !== false) kopf.hauptaktion = { text: 'Diesen Ordner wählen', aktion: 'sh_ordner_waehlen', werte: { bericht_id: bid, pfad: pf } };
    const soO = sortierung('ordner', ['name'], { spalte: 'name', richtung: 'auf' });
    const ORD = sortiere(L(OL.eintraege).filter(e => e && e.ordner && s(e.name)), soO, e => s(e.name));
    const hoch = teile.length ? [{ zellen: { name: { text: '‹ Eine Ebene höher', ziel: zu(teile.slice(0, -1).join('/')) }, aktion: '' } }] : [];
    inhalt.push({ typ: 'tabelle', id: 'ordner', titel: 'Ordner in ' + [BER].concat(teile).join(' › '), leer: 'Hier gibt es keine Unterordner.', je_seite: 500,
      spalten: [{ schluessel: 'name', titel: 'Ordner', sortierbar: true }, { schluessel: 'aktion', titel: 'Aktion' }], sortierung: soO, seite: 1, gesamt: ORD.length,
      zeilen: hoch.concat(ORD.map(e => { const p = (pf ? pf + '/' : '') + s(e.name); const ok = p.length <= 280;
